script:
if (-not $USERNAME) { throw 'USERNAME is required' }
$secure = $null
if ($PASSWORD) { $secure = ConvertTo-SecureString $PASSWORD -AsPlainText -Force }
$existing = Get-ADUser -Filter "SamAccountName -eq '$USERNAME'" -ErrorAction Ignore
if ($existing) {
    $u = @{}
    if ($FULLNAME) { $u.DisplayName = $FULLNAME }
    if ($DESCRIPTION) { $u.Description = $DESCRIPTION }
    if ($u.Count) { Set-ADUser -Identity $USERNAME @u }
    if ($secure) { Set-ADAccountPassword -Identity $USERNAME -Reset -NewPassword $secure }
    Set-ADUser -Identity $USERNAME -Enabled $true
} else {
    if (-not $secure) { throw "PASSWORD is required to create AD user '$USERNAME' (New-ADUser cannot enable a passwordless account)" }
    $params = @{ Name = $USERNAME; SamAccountName = $USERNAME; Enabled = $true; AccountPassword = $secure }
    if ($FULLNAME) { $params.DisplayName = $FULLNAME }
    if ($DESCRIPTION) { $params.Description = $DESCRIPTION }
    if ($NEVER_EXPIRES -eq '1') { $params.PasswordNeverExpires = $true }
    New-ADUser @params | Out-Null
}
if ($NEVER_EXPIRES -eq '1') { Set-ADUser -Identity $USERNAME -PasswordNeverExpires $true }
if ($SPN) {
    $cur = (Get-ADUser -Identity $USERNAME -Properties ServicePrincipalNames).ServicePrincipalNames
    if ($cur -notcontains $SPN) { Set-ADUser -Identity $USERNAME -ServicePrincipalNames @{ Add = $SPN } }
}
if ($NO_PREAUTH -eq '1') { Set-ADAccountControl -Identity $USERNAME -DoesNotRequirePreAuth $true }
if ($DES_ONLY -eq '1') { Set-ADUser -Identity $USERNAME -KerberosEncryptionType DES }
